class Image(val path: String = "") {
    private var drawingColor = "rgb(0,0,0)"
    private var drawingOperations = mutableListOf<String>()
    private var imageWidth = 30
    private var imageHeight = 30
    var transparency = 255
        set(value) { field = if (value < 0) 0 else if (value > 255) 255 else value }

    val width: Int get() = imageWidth
    val height: Int get() = imageHeight

    fun setTransparency(value: Int) { transparency = value }
    fun scale(newWidth: Int, newHeight: Int) {
        imageWidth = if (newWidth < 1) 1 else newWidth
        imageHeight = if (newHeight < 1) 1 else newHeight
    }
    fun setColor(red: Int, green: Int, blue: Int) {
        drawingColor = "rgb($red,$green,$blue)"
    }
    fun fill() { drawingOperations = mutableListOf("fill|$drawingColor") }
    fun fillRect(x: Int, y: Int, width: Int, height: Int) {
        drawingOperations.add("fillRect|$x|$y|$width|$height|$drawingColor")
    }
    fun drawRect(x: Int, y: Int, width: Int, height: Int) {
        drawingOperations.add("drawRect|$x|$y|$width|$height|$drawingColor")
    }
    fun fillOval(x: Int, y: Int, width: Int, height: Int) {
        drawingOperations.add("fillOval|$x|$y|$width|$height|$drawingColor")
    }
    fun drawOval(x: Int, y: Int, width: Int, height: Int) {
        drawingOperations.add("drawOval|$x|$y|$width|$height|$drawingColor")
    }
    fun drawLine(x1: Int, y1: Int, x2: Int, y2: Int) {
        drawingOperations.add("drawLine|$x1|$y1|$x2|$y2|$drawingColor")
    }
    fun drawString(text: String, x: Int, y: Int) {
        var encoded = ""
        var index = 0
        while (index < text.length) {
            val character = text.substring(index, index + 1)
            encoded += if (character == "\\") "\\\\" else if (character == "|") "\\p" else if (character == "\n") "\\n" else character
            index += 1
        }
        drawingOperations.add("drawString|$encoded|$x|$y|$drawingColor")
    }
    fun drawImage(image: Image, x: Int, y: Int) {
        val nested = "{\"operations\":${image.drawingJson()},\"width\":${image.width},\"height\":${image.height}}"
        var encoded = ""
        var index = 0
        while (index < nested.length) {
            val character = nested.substring(index, index + 1)
            encoded += if (character == "\\") "\\\\" else if (character == "\"") "\\\"" else if (character == "|") "\\p" else if (character == "\n") "\\n" else character
            index += 1
        }
        drawingOperations.add("drawImage|__bluek:$encoded|$x|$y|${image.width}|${image.height}")
    }
    fun clear() { drawingOperations.clear() }

    fun drawingJson(): String {
        var json = "["
        var index = 0
        while (index < drawingOperations.size) {
            if (index > 0) json += ","
            val operation = drawingOperations[index]
            var escaped = ""
            var characterIndex = 0
            while (characterIndex < operation.length) {
                val character = operation.substring(characterIndex, characterIndex + 1)
                escaped += if (character == "\\") "\\\\" else if (character == "\"") "\\\"" else if (character == "\n") "\\n" else character
                characterIndex += 1
            }
            json += "\"$escaped\""
            index += 1
        }
        return "$json]"
    }
}

open class Actor {
    var x = 0
    var y = 0
    var rotation = 0
    var image: Image? = null
    var worldWidth = 0
    var worldHeight = 0
    var worldCellSize = 1
    fun setImage(path: String) { image = Image(path) }
    fun setImage(newImage: Image) { image = newImage }
    fun getImage(): Image? = image
    fun getX(): Int = x
    fun getY(): Int = y
    fun setLocation(newX: Int, newY: Int) {
        x = if (worldWidth > 0) {
            if (newX < 0) 0 else if (newX >= worldWidth) worldWidth - 1 else newX
        } else newX
        y = if (worldHeight > 0) {
            if (newY < 0) 0 else if (newY >= worldHeight) worldHeight - 1 else newY
        } else newY
    }
    fun getRotation(): Int = rotation
    fun setRotation(degrees: Int) { rotation = degrees }
    fun turnTowards(targetX: Int, targetY: Int) { rotation = bluekHeading(x, y, targetX, targetY) }
    fun distanceTo(other: Actor): Int = bluekDistance(x, y, other.x, other.y)
    fun intersects(other: Actor): Boolean {
        val firstImage = image
        val secondImage = other.image
        val firstWidth = firstImage?.width ?: 30
        val firstHeight = firstImage?.height ?: 30
        val secondWidth = secondImage?.width ?: 30
        val secondHeight = secondImage?.height ?: 30
        val firstCenterX = x * worldCellSize + worldCellSize / 2
        val firstCenterY = y * worldCellSize + worldCellSize / 2
        val secondCenterX = other.x * other.worldCellSize + other.worldCellSize / 2
        val secondCenterY = other.y * other.worldCellSize + other.worldCellSize / 2
        return (firstCenterX - secondCenterX) * 2 < firstWidth + secondWidth &&
            (firstCenterY - secondCenterY) * 2 < firstHeight + secondHeight &&
            (secondCenterX - firstCenterX) * 2 < firstWidth + secondWidth &&
            (secondCenterY - firstCenterY) * 2 < firstHeight + secondHeight
    }
    fun isTouching(other: Actor): Boolean = intersects(other)
    open fun act() {}
    fun move(distance: Int) {
        val normalized = ((rotation % 360) + 360) % 360
        if (normalized == 90) setLocation(x, y + distance)
        else if (normalized == 180) setLocation(x - distance, y)
        else if (normalized == 270) setLocation(x, y - distance)
        else setLocation(x + distance, y)
    }
    fun turn(degrees: Int) { rotation += degrees }
    val isAtEdge: Boolean get() = worldWidth > 0 && worldHeight > 0 && (x <= 0 || y <= 0 || x >= worldWidth - 1 || y >= worldHeight - 1)
    val isClicked: Boolean get() = bluekIsActorClicked(x, y)
}

fun bluekEscape(value: String): String {
    var escaped = ""
    var index = 0
    while (index < value.length) {
        val character = value.substring(index, index + 1)
        if (character == "\"") escaped += "\\\""
        else if (character == "\\") escaped += "\\\\"
        else if (character == "\n") escaped += "\\n"
        else escaped += character
        index += 1
    }
    return escaped
}

open class World(val width: Int, val height: Int, val cellSize: Int = 1) {
    private val actors = mutableListOf<Actor>()
    private val textX = mutableListOf<Int>()
    private val textY = mutableListOf<Int>()
    private val textValues = mutableListOf<String>()
    var backgroundColor = "rgb(255,255,255)"
    var background = Image("")
    var running = false
    var speed = 50
    fun actorType(actor: Actor): String = "Actor"
    fun render() {
        var objects = "["
        var first = true
        for (current in actors) {
            if (!first) objects += ","
            first = false
            val imagePath = current.image?.path ?: ""
            val imageOperations = current.image?.drawingJson() ?: "[]"
            val imageWidth = current.image?.width ?: 30
            val imageHeight = current.image?.height ?: 30
            val imageOpacity = current.image?.transparency?.toString() ?: "255"
            objects += "{\"type\":\"${actorType(current)}\",\"x\":${current.x},\"y\":${current.y},\"rotation\":${current.rotation},\"imagePath\":\"${bluekEscape(imagePath)}\",\"imageOperations\":$imageOperations,\"imageWidth\":$imageWidth,\"imageHeight\":$imageHeight,\"imageOpacity\":${imageOpacity.toDouble() / 255.0}}"
        }
        objects += "]"
        val backgroundPath = background.path
        var texts = "["
        var textFirst = true
        var textIndex = 0
        while (textIndex < textValues.size) {
            if (!textFirst) texts += ","
            textFirst = false
            texts += "{\"x\":${textX[textIndex]},\"y\":${textY[textIndex]},\"text\":\"${bluekEscape(textValues[textIndex])}\"}"
            textIndex += 1
        }
        texts += "]"
        bluekStageUpdate("{\"stage\":{\"width\":${width},\"height\":${height},\"cellSize\":${cellSize},\"backgroundColor\":\"${bluekEscape(backgroundColor)}\",\"backgroundPath\":\"${bluekEscape(backgroundPath)}\",\"backgroundOperations\":${background.drawingJson()},\"speed\":${speed},\"running\":${running},\"objects\":${objects},\"texts\":${texts}}}")
    }
    fun show() { render() }
    fun getWidth(): Int = width
    fun getHeight(): Int = height
    fun getCellSize(): Int = cellSize
    fun setBackground(fileName: String) { background = Image(fileName); show() }
    fun setBackground(red: Int, green: Int, blue: Int) {
        backgroundColor = "rgb(${red},${green},${blue})"
        background = Image("")
        show()
    }
    fun showText(text: String, x: Int, y: Int) {
        var index = 0
        while (index < textValues.size) {
            if (textX[index] == x && textY[index] == y) {
                if (text.isEmpty()) {
                    textX.removeAt(index)
                    textY.removeAt(index)
                    textValues.removeAt(index)
                } else {
                    textValues[index] = text
                }
                show()
                return
            }
            index += 1
        }
        if (text.isNotEmpty()) {
            textX.add(x)
            textY.add(y)
            textValues.add(text)
        }
        show()
    }
    open fun act() {}
    fun tick() { act(); for (current in actors) current.act() }
    fun addObject(actor: Actor, x: Int, y: Int) {
        if (actors.count { it == actor } == 0) {
            actors.add(actor)
        }
        actor.worldWidth = width
        actor.worldHeight = height
        actor.worldCellSize = cellSize
        actor.setLocation(x, y)
        show()
    }
    fun getObjects(): List<Actor> = actors
    fun removeObject(actor: Actor) {
        if (actors.count { it == actor } > 0) {
            actors.remove(actor)
        }
        show()
    }
    fun allObjects(): List<Actor> = actors
    fun getObjectsAt(x: Int, y: Int): List<Actor> = actors.filter { it.x == x && it.y == y }
    val numberOfObjects: Int get() = actors.size
    val isClicked: Boolean get() = bluekIsWorldClicked()
}

// Browser-only BluePlay bridge. The visible world is rendered by BlueK.
var currentWorld: World?
fun activeWorld(): World = currentWorld as World
fun isKeyDown(key: String): Boolean = bluekIsKeyDown(key)
fun showWorld(world: World) { currentWorld = world; world.show() }
fun show() { showWorld(activeWorld()) }
fun start() { activeWorld().running = true; activeWorld().show() }
fun stop() { activeWorld().running = false; activeWorld().show() }
fun step() { activeWorld().tick(); activeWorld().show() }
fun setSpeed(value: Int) { activeWorld().speed = if (value < 1) 1 else if (value > 100) 100 else value; activeWorld().show() }
fun getSpeed(): Int = activeWorld().speed
fun playSound(fileName: String) { bluekPlaySound(fileName) }
